SINA_SMART["physio1-colon-motility"] = {"lecture":"physio1-colon-motility","title":"Colon motility","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-colon-motility:e0","text":"Colon ~1.5 m; taeniae coli and haustra.","topic":"Anatomy and functions","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e1","text":"Proximal colon absorbs; distal colon stores.","topic":"Anatomy and functions","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e2","text":"Haustral contractions mix; propulsive contractions move slowly.","topic":"Motor patterns","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e3","text":"Retrograde contractions delay transit towards the caecum.","topic":"Motor patterns","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e4","text":"HAPCs (mass movements) fill the rectum, often after meals.","topic":"Motor patterns","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e5","text":"Gastrocolic reflex: meal → colonic activity.","topic":"Control","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e6","text":"Pacemaker: interstitial cells of Cajal (2-6/min).","topic":"Control","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e7","text":"Parasympathetic excites (vagus, S2-S4); sympathetic inhibits.","topic":"Control","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-colon-motility:e8","text":"Hirschsprung: aganglionic distal bowel; rectal biopsy.","topic":"Tests and disorders","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"kocfce":"a","yznd1n":"a","x89vg2":"a","h97qqs":"a","17wc85x":"a","16aod2r":"a","1y7cy87":"a","4dun0j":"a","nnrp8i":"a","syw6ez":"a","1ope6ep":"a","gdq1f3":"a","1hh5lbh":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-colon-motility:e0":{"s":0,"u":["Colon ~1.5 m; taeniae coli and haustra.","Its longitudinal muscle is gathered into three bands, the taeniae coli ; the sacculations between them are the haustra .","The colon runs about 1.5 m from the caecum through ascending, transverse, descending and sigmoid colon to the rectum."],"dp":[]},"physio1-colon-motility:e1":{"s":0,"u":["Proximal colon absorbs; distal colon stores.","The colon secretes mainly mucus (almost no enzymes), absorbs water and electrolytes (mostly in the proximal 'absorptive' colon; up to 5-8 L/day if needed), absorbs bacterial vitamins such as vitamin K , ferments residue and stores faeces in the distal 'storage' colon.","The colon runs about 1.5 m from the caecum through ascending, transverse, descending and sigmoid colon to the rectum."],"dp":[]},"physio1-colon-motility:e2":{"s":1,"u":["Haustral contractions mix; propulsive contractions move slowly.","Haustral segmental contractions : non-propulsive, low-amplitude ring contractions in the proximal colon that mix contents for absorption and fermentation.","Propulsive peristaltic contractions : low- to medium-amplitude, in the transverse and descending colon; each lasts about 30 s and series last 10-30 min, moving faeces slowly towards the sigmoid."],"dp":[]},"physio1-colon-motility:e3":{"s":1,"u":["Retrograde contractions delay transit towards the caecum.","Retrograde contractions : from the ascending-transverse junction back towards the caecum, delaying transit to favour absorption."],"dp":[]},"physio1-colon-motility:e4":{"s":1,"u":["HAPCs (mass movements) fill the rectum, often after meals.","High-amplitude propagating contractions (HAPCs) or mass movements : a few times a day, especially after meals, pushing stool into the rectosigmoid and preceding the urge to defecate."],"dp":[{"h":"Why babies need a nappy change right after feeding","t":"The gastrocolic reflex is especially strong in infants: a feed distends the stomach and triggers mass movements within minutes, so a bowel motion often follows the meal. Adults feel the same reflex as the urge to go after breakfast, and people with irritable bowel syndrome often feel it exaggerated."}]},"physio1-colon-motility:e5":{"s":2,"u":["Gastrocolic reflex: meal → colonic activity.","Reflexes : gastrocolic (meal → colonic activity), rectocolonic (rectal distension relaxes the proximal colon) and the defecation reflex ."],"dp":[]},"physio1-colon-motility:e6":{"s":2,"u":["Pacemaker: interstitial cells of Cajal (2-6/min).","Myogenic : interstitial cells of Cajal generate slow waves (about 2-6/min); depolarisation depends on Ca²⁺ entry through L-type channels."],"dp":[]},"physio1-colon-motility:e7":{"s":2,"u":["Parasympathetic excites (vagus, S2-S4); sympathetic inhibits.","Extrinsic : parasympathetic, from the vagus to the proximal colon and from the pelvic splanchnic nerves (S2-S4) to the distal colon and rectum (excitatory); sympathetic from T10-L2 via hypogastric nerves (inhibitory, raises sphincter tone); afferents carry distension and pain."],"dp":[]},"physio1-colon-motility:e8":{"s":3,"u":["Hirschsprung: aganglionic distal bowel; rectal biopsy.","Hirschsprung disease : congenital absence of ganglion cells in the distal bowel → functional obstruction, delayed passage of meconium, distension, explosive stool after rectal examination; diagnosed by rectal biopsy (gold standard) and anorectal manometry (absent recto-anal inhibitory reflex)."],"dp":[]}},"meta":{"kocfce":{"a":"recall","vg":"physio1-colon-motility:e0/recall/1"},"yznd1n":{"a":"recall","vg":"physio1-colon-motility:e1/recall/1"},"x89vg2":{"a":"recall","vg":"physio1-colon-motility:e2/recall/1"},"h97qqs":{"a":"recall","vg":"physio1-colon-motility:e4/recall/1"},"17wc85x":{"a":"recall","vg":"physio1-colon-motility:e5/recall/1"},"16aod2r":{"a":"recall","vg":"physio1-colon-motility:e6/recall/1"},"1y7cy87":{"a":"recall","vg":"physio1-colon-motility:e7/recall/1"},"4dun0j":{"a":"recall","vg":"physio1-colon-motility:e7/recall/2"},"nnrp8i":{"a":"relationship","vg":"physio1-colon-motility:e8/relationship/1"},"syw6ez":{"a":"recall","vg":"physio1-colon-motility:e8/recall/1"},"1ope6ep":{"a":"recall","vg":"physio1-colon-motility:e3/recall/1"},"gdq1f3":{"a":"recall","vg":"physio1-colon-motility:e3/recall/2"},"1hh5lbh":{"a":"recall","vg":"physio1-colon-motility:e1/recall/2"}},"explRev":"08739111d1da"};
